#[derive(Default)]struct Store(Mutex<std::collections::BTreeMap<String,Vec<u8>>>);
impl secret::CredentialStore for Store{
 fn save(&self,p:&secret::ServiceProfile,b:&secret::SecretBlob)->Result<(),secret::StoreError>{self.0.lock().unwrap().insert(format!("{p:?}"),b.bytes().to_vec());Ok(())}
 fn load(&self,p:&secret::ServiceProfile)->Result<Option<secret::SecretBlob>,secret::StoreError>{self.0.lock().unwrap().get(&format!("{p:?}")).map(|b|secret::SecretBlob::new(b.clone())).transpose()}
 fn delete(&self,p:&secret::ServiceProfile)->Result<(),secret::StoreError>{self.0.lock().unwrap().remove(&format!("{p:?}"));Ok(())}
}
fn staged(root:&std::path::Path)->crate::handoff::Pending{
 let config=serde_json::json!({"seed":424242,"seedPolicy":"shared-fixed","randomizeLoot":true});let digest=nt2_desktop_g0::protocol_connection::canonical_fingerprint(&serde_json::to_vec(&config).unwrap()).unwrap();
 let scope=Scope{origin:"https://native-startup.invalid".into(),service:"native-startup".into(),service_epoch:"service-epoch".into(),account:"account".into(),device:uuid::Uuid::new_v4(),desktop:"desktop".into(),desktop_epoch:"desktop-epoch".into(),room:"room".into(),run:"run".into(),run_epoch:"run-epoch".into(),config:7,config_digest:digest,preparation:"preparation".into()};
 let b=Prepared::stage_durable(&Store::default(),scope,424242,5,7,Instant::now()+Duration::from_secs(60),config).unwrap();let mut p=crate::handoff::new(424242,"run".into(),7);p.epoch="run-epoch".into();p.world_policy=5;p.native_v2=true;p.expires=Instant::now()+Duration::from_secs(60);p.authority_until=Instant::now()+Duration::from_secs(12);p.preparation_id=Some("preparation".into());p.generation=Some((Arc::new(std::sync::atomic::AtomicU64::new(7)),7));p.startup_ready=true;p.startup_bundle=Some(Arc::new(b));p.claim_path=Some(root.join("claims/original"));p
}
fn request(op:u32,context:[u8;16])->Vec<u8>{let mut r=vec![0;32];r[..4].copy_from_slice(&crate::handoff::MAGIC.to_le_bytes());r[4..8].copy_from_slice(&9u32.to_le_bytes());r[8..12].copy_from_slice(&op.to_le_bytes());r[16..32].copy_from_slice(&context);r}
#[test]fn se1_r3_production_dispatch_keeps_delayed_canonical_original_across_passive_b(){
 let root=std::env::temp_dir().join(format!("nt2-se1-route-{}",uuid::Uuid::new_v4()));let a=staged(&root);let bundle=a.startup_bundle.clone().unwrap();let context=*bundle.world().as_bytes();let pending=Arc::new(Mutex::new(Some(a)));let lane=Lane::new(pending.clone());
 let dispatch=|b:Option<&Arc<super::super::entry::Bridge>>,q:&[u8],delay|super::super::dispatch_startup(&lane,b,nt2_local_ws::owner::Id::OsProcess(7),100,q,delay);
 let offer=request(19,[17;16]);let original=dispatch(None,&offer,Duration::ZERO);assert_eq!(original[12],2);assert_eq!(dispatch(None,&request(16,context),Duration::from_millis(150))[12],2);
 let(worker,v,_)=super::super::entry::tests::staged(super::super::entry::tests::preview());let b=Arc::new(super::super::entry::Bridge::new(worker));
 assert_eq!(super::super::dispatch_startup(&lane,Some(&b),nt2_local_ws::owner::Id::OsProcess(7),101,&offer,Duration::ZERO)[12],0,"PID reuse cannot turn an old A bootstrap into a fresh B offer");assert!(!b.worker.fresh_started());
 assert_eq!(dispatch(Some(&b),&offer,Duration::ZERO),original);assert_eq!(dispatch(Some(&b),&request(16,context),Duration::ZERO)[12],2);
 let until=Instant::now()+Duration::from_secs(3);loop{let r=dispatch(Some(&b),&request(18,context),Duration::ZERO);assert_eq!(r[176],0);if r[12]==1{break}assert!(Instant::now()<until);thread::sleep(Duration::from_millis(2));}
 assert_eq!(dispatch(Some(&b),&request(19,[18;16]),Duration::ZERO)[176],1);assert_eq!(dispatch(Some(&b),&request(16,*v.context.as_bytes()),Duration::ZERO)[12],2);super::super::entry::tests::ready(&b.worker);assert_eq!(dispatch(Some(&b),&request(18,*v.context.as_bytes()),Duration::ZERO)[12],1);
 let mut close=request(17,context);close.extend(bundle.world().as_bytes());close.extend(hex(bundle.digest()));dispatch(Some(&b),&close,Duration::ZERO);assert!(pending.lock().unwrap().is_none());assert!(b.pending.lock().unwrap().is_some());assert_eq!(dispatch(Some(&b),&offer,Duration::ZERO)[12],0,"old A offer cannot rebind to B");assert_eq!(dispatch(Some(&b),&request(18,*v.context.as_bytes()),Duration::ZERO)[12],1);
 assert_eq!(super::super::dispatch_startup(&lane,Some(&b),nt2_local_ws::owner::Id::OsProcess(7),101,&request(18,*v.context.as_bytes()),Duration::ZERO)[12],0);drop(lane);assert!(root.canonicalize().unwrap().starts_with(std::env::temp_dir().canonicalize().unwrap()));std::fs::remove_dir_all(root).unwrap();
}
#[test]fn startup_repair_offlock_exact_original_lost_reply_and_stale_cancel(){
 let root=std::env::temp_dir().join(format!("nt2-startup-unit-{}",uuid::Uuid::new_v4()));let p=staged(&root);let b=p.startup_bundle.clone().unwrap();let context=*b.world().as_bytes();let pending=Arc::new(Mutex::new(Some(p)));let lane=Lane::new(pending.clone());let req=request(16,context);
 let queued=lane.handle(nt2_local_ws::owner::Id::OsProcess(123),&req,Duration::from_millis(250));assert_eq!(queued[12],QUEUED as u8);assert_eq!(queued[20],0);let before=Instant::now();{let _p=pending.lock().unwrap();}assert!(before.elapsed()<Duration::from_millis(20));
 let until=Instant::now()+Duration::from_secs(2);let first=loop{let r=lane.handle(nt2_local_ws::owner::Id::OsProcess(123),&request(18,context),Duration::ZERO);if r[12]==1{break r}assert!(Instant::now()<until);thread::sleep(Duration::from_millis(2));};let again=lane.handle(nt2_local_ws::owner::Id::OsProcess(123),&req,Duration::ZERO);assert_eq!(&first[64..160],&again[64..160]);assert_eq!(u32::from_le_bytes(first[20..24].try_into().unwrap()),424242);assert_eq!(u32::from_le_bytes(first[24..28].try_into().unwrap()),5);assert!(root.join("claims/original.startup.json").is_file());assert_eq!(std::fs::read(root.join("claims/original")).unwrap().len(),20);
 assert_eq!(lane.handle(nt2_local_ws::owner::Id::OsProcess(124),&req,Duration::ZERO)[16],OWNER as u8);assert_eq!(lane.handle_instance(nt2_local_ws::owner::Id::OsProcess(123),2,&req,Duration::ZERO)[16],OWNER as u8,"PID reuse must not recover original seed");let mut cancel=request(17,context);cancel.extend_from_slice(b.world().as_bytes());cancel.extend_from_slice(&hex(b.digest()));pending.lock().unwrap().as_mut().unwrap().config+=1;lane.handle(nt2_local_ws::owner::Id::OsProcess(123),&cancel,Duration::ZERO);assert!(pending.lock().unwrap().is_some(),"Old close cannot cancel changed configuration");assert_eq!(lane.handle(nt2_local_ws::owner::Id::OsProcess(123),&req,Duration::ZERO)[12],0);drop(lane);assert!(root.canonicalize().unwrap().starts_with(std::env::temp_dir().canonicalize().unwrap()));std::fs::remove_dir_all(root).unwrap();
}
fn settled(lane:&Lane,pid:crate::local_owner::Id,birth:u64,ctx:[u8;16])->Vec<u8>{let until=Instant::now()+Duration::from_secs(3);loop{let r=lane.handle_instance(pid,birth,&request(16,ctx),Duration::ZERO);if r[12]!=QUEUED as u8{return r}assert!(Instant::now()<until);thread::sleep(Duration::from_millis(2));}}
#[test]fn startup_repair_restart_disk_fault_capacity_and_old_close_are_fenced(){
 let root=std::env::temp_dir().join(format!("nt2-startup-cuts-{}",uuid::Uuid::new_v4()));
 let p=staged(&root);let b=p.startup_bundle.clone().unwrap();let ctx=*b.world().as_bytes();let slot=Arc::new(Mutex::new(Some(p.clone())));let lane=Lane::new(slot.clone());assert_eq!(settled(&lane,nt2_local_ws::owner::Id::OsProcess(91),100,ctx)[12],1);drop(lane);
 // Simulated app restart: same protected original and still-running process
 // reconcile exact disk bytes. The same numeric PID with another birth cannot.
 *slot.lock().unwrap()=Some(p.clone());let lane=Lane::new(slot.clone());assert_eq!(settled(&lane,nt2_local_ws::owner::Id::OsProcess(91),100,ctx)[12],1);drop(lane);
 *slot.lock().unwrap()=Some(p.clone());let lane=Lane::new(slot.clone());assert_eq!(settled(&lane,nt2_local_ws::owner::Id::OsProcess(91),101,ctx)[16],DURABILITY as u8);drop(lane);
 // Replacement is a distinct app-owned world. An exact old cancellation must
 // not retire it, including when the process and numeric generation are equal.
 let replacement=staged(&root.join("replacement"));let new_context=*replacement.startup_bundle.as_ref().unwrap().world().as_bytes();*slot.lock().unwrap()=Some(replacement);let lane=Lane::new(slot.clone());assert_eq!(settled(&lane,nt2_local_ws::owner::Id::OsProcess(91),101,new_context)[12],1);let mut close=request(17,ctx);close.extend_from_slice(b.world().as_bytes());close.extend_from_slice(&hex(b.digest()));lane.handle_instance(nt2_local_ws::owner::Id::OsProcess(91),100,&close,Duration::ZERO);assert!(slot.lock().unwrap().is_some());assert_eq!(settled(&lane,nt2_local_ws::owner::Id::OsProcess(91),101,new_context)[12],1);drop(lane);
 let damaged=root.join("damaged");let p=staged(&damaged);let ctx=*p.startup_bundle.as_ref().unwrap().world().as_bytes();std::fs::create_dir_all(damaged.join("claims")).unwrap();std::fs::write(damaged.join("claims/original.startup.json"),b"partial").unwrap();*slot.lock().unwrap()=Some(p);let lane=Lane::new(slot.clone());assert_eq!(settled(&lane,nt2_local_ws::owner::Id::OsProcess(91),101,ctx)[16],DURABILITY as u8);drop(lane);
 let full=root.join("full");let p=staged(&full);let ctx=*p.startup_bundle.as_ref().unwrap().world().as_bytes();std::fs::create_dir_all(full.join("claims")).unwrap();for n in 0..384{std::fs::write(full.join(format!("claims/{n}")),b"bounded").unwrap()}*slot.lock().unwrap()=Some(p);let lane=Lane::new(slot.clone());assert_eq!(settled(&lane,nt2_local_ws::owner::Id::OsProcess(91),101,ctx)[16],CAPACITY as u8);assert!(!full.join("claims/original").exists());drop(lane);
 let blocked=root.join("blocked");std::fs::write(&blocked,b"directory unavailable").unwrap();let p=staged(&blocked);let ctx=*p.startup_bundle.as_ref().unwrap().world().as_bytes();*slot.lock().unwrap()=Some(p);let lane=Lane::new(slot);assert_eq!(settled(&lane,nt2_local_ws::owner::Id::OsProcess(91),101,ctx)[16],DURABILITY as u8);drop(lane);
 assert!(root.canonicalize().unwrap().starts_with(std::env::temp_dir().canonicalize().unwrap()));std::fs::remove_dir_all(root).unwrap();
}
#[test]#[ignore="hidden real production wrapper/broker/Rust pipe; no DB, injected engine entry only"]
fn startup_repair_real_production_native_pipe(){
 use std::process::{Command,Stdio};use std::os::windows::process::CommandExt;
 let repo=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..").canonicalize().unwrap();let repo=std::path::PathBuf::from(repo.to_str().unwrap().trim_start_matches(r"\\?\"));let root=repo.join("spikes/noita-entry/.build/g3-startup-repair-client-20261017-01").join(format!("real-native-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&root).unwrap();let prefix=format!(r"\\.\pipe\nt2-startup-repair-{}-",uuid::Uuid::new_v4());let image=super::super::verified_process_path(&std::env::current_exe().unwrap()).unwrap();
 let build=Command::new("powershell.exe").args(["-NoProfile","-ExecutionPolicy","Bypass","-File"]).arg(repo.join("native/g3-ipc/build.ps1")).arg("-OutputDirectory").arg(root.join("dlls")).arg("-Private").arg("-TestAppPath").arg(&image).arg("-TestPipePrefix").arg(&prefix).creation_flags(0x08000000).output().unwrap();std::fs::write(root.join("build.txt"),&build.stdout).unwrap();assert!(build.status.success(),"{}",String::from_utf8_lossy(&build.stderr));
 let runner=repo.join("spikes/noita-entry/.build/Lua51Runner.exe");let mut evidence=vec![];
 for (case,delay,budget,expect,loader_delay) in [("cold",0,6000,true,0),("delay250",250,6000,true,0),("delay1000",1000,6000,true,0),("delay3500",3500,6000,true,0),("lost-reply",250,6000,true,0),("old-files",0,6000,true,0),("busy-pipe",0,6000,true,0),("retained-explicit-entry",0,6000,true,0),("changed-owner",1000,6000,false,0),("no-pipe",0,250,false,0),("over-budget",1500,300,false,0),("changed-config",1000,6000,false,0),("loader250",0,6000,true,250),("loader1000",0,6000,true,1000),("loader3500",0,6000,true,3500),("loader-over-budget",0,300,false,1500)]{
  let own=root.join(case);std::fs::create_dir_all(&own).unwrap();let dlls=if loader_delay>0{let dlls=own.join("dlls");let build=Command::new("powershell.exe").args(["-NoProfile","-ExecutionPolicy","Bypass","-File"]).arg(repo.join("native/g3-ipc/build.ps1")).arg("-OutputDirectory").arg(&dlls).arg("-Private").arg("-TestAppPath").arg(&image).arg("-TestPipePrefix").arg(&prefix).arg("-TestLoaderDelayMs").arg(loader_delay.to_string()).creation_flags(0x08000000).output().unwrap();std::fs::write(own.join("loader-build.txt"),&build.stdout).unwrap();assert!(build.status.success(),"{}",String::from_utf8_lossy(&build.stderr));dlls}else{root.join("dlls")};
  let pending=Arc::new(Mutex::new(Some(staged(&own))));let stop=Arc::new(AtomicBool::new(false));let diagnostics=Arc::new(Mutex::new(super::super::NativeDiagnostics::default()));diagnostics.lock().unwrap().startup_claim_delay_ms=delay;diagnostics.lock().unwrap().startup_drop_ready_once=case=="lost-reply";
  let expected=Arc::new(Mutex::new(Some(runner.clone())));let endpoint=format!("{prefix}{}",super::super::user_sid().unwrap());let start_listener=||super::super::start_g3_social_named(endpoint.clone(),pending.clone(),stop.clone(),expected.clone(),diagnostics.clone(),Arc::new(Mutex::new(nt2_desktop_g0::g3_runtime::Exchange::default())),Arc::new(Mutex::new(nt2_desktop_g0::g3_social_stream::Exchange::default()))).unwrap();let mut listener=if matches!(case,"no-pipe"|"busy-pipe"){None}else{Some(start_listener())};
  if case=="old-files"{let save=own.join("LocalLow/Nolla_Games_Noita/save00");std::fs::create_dir_all(&save).unwrap();std::fs::write(save.join("world_state.xml"),b"isolated old save sentinel").unwrap();std::fs::write(save.join("player.xml"),b"isolated old player sentinel").unwrap();}
  // Occupy the only instance before starting production listener. Unlike an
  // untrusted parent contact to that listener, this cannot be closed by its
  // image guard. Prove ERROR_PIPE_BUSY, then replace only this disposable pipe
  // with the real Rust listener after200ms; broker must reacquire before write.
  let busy=if case=="busy-pipe"{let name=super::super::wide(&endpoint);let server=unsafe{super::super::CreateNamedPipeW(name.as_ptr(),3|0x80000,4|2|1|8,1,16384,32768,0,std::ptr::null())};assert!(server as isize != -1&&!server.is_null());let server=super::super::Owned(server);let client=unsafe{CreateFileW(name.as_ptr(),0xc0000000,0,std::ptr::null_mut(),3,0,std::ptr::null_mut())};assert!(client as isize != -1&&!client.is_null());let client=super::super::Owned(client);let probe=unsafe{CreateFileW(name.as_ptr(),0xc0000000,0,std::ptr::null_mut(),3,0,std::ptr::null_mut())};assert_eq!(probe as isize,-1);assert_eq!(unsafe{super::super::GetLastError()},231,"Fixture must actually saturate the pipe");Some((server,client))}else{None};
  let mut child=Command::new(&runner).arg("C:/Noita/lua51.dll").arg(repo.join("apps/desktop/tools/startup-repair-native-test.lua")).env("NT2_STARTUP_LOADER_DELAY",loader_delay.to_string()).env("NT2_STARTUP_RETAINED",if case=="retained-explicit-entry"{own.to_string_lossy().to_string()}else{String::new()}).env("NT2_STARTUP_REPO",&repo).env("NT2_STARTUP_DLLS",dlls).env("NT2_STARTUP_BUDGET",budget.to_string()).env("NT2_STARTUP_EXPECT",if expect{"1"}else{"0"}).env("APPDATA",own.join("Roaming")).stdout(Stdio::piped()).stderr(Stdio::piped()).creation_flags(0x08000000).spawn().unwrap();
  let began=Instant::now();let mut busy=busy;let mut maximum_lock=0u128;let mut queued_samples=0u64;let mut changed=false;let mut replaced=false;let until=Instant::now()+Duration::from_secs(10);
  loop{if case=="retained-explicit-entry"&&!replaced&&own.join("first.done").is_file(){*pending.lock().unwrap()=Some(staged(&own.join("replacement")));std::fs::write(own.join("new.ready"),b"injected distinct new-world entry").unwrap();replaced=true;}if began.elapsed()>Duration::from_millis(200)&&busy.is_some(){drop(busy.take());listener=Some(start_listener());}let before=Instant::now();if let Ok(mut p)=pending.try_lock(){if p.as_ref().is_some_and(|p|p.startup_transaction.as_ref().is_some_and(|a|a.result.lock().unwrap().state==QUEUED)){queued_samples+=1;}if case=="changed-owner"&&!changed&&p.as_ref().is_some_and(|p|p.owner.is_some()){p.as_mut().unwrap().owner=Some((nt2_local_ws::owner::Id::OsProcess(999),[9;16]));changed=true;}if case=="changed-config"&&!changed&&p.as_ref().is_some_and(|p|p.owner.is_some()){p.as_mut().unwrap().config+=1;changed=true;}}maximum_lock=maximum_lock.max(before.elapsed().as_micros());if child.try_wait().unwrap().is_some(){break}assert!(Instant::now()<until,"bounded wrapper child did not finish; no termination attempted");thread::sleep(Duration::from_millis(2));}
  let output=child.wait_with_output().unwrap();std::fs::write(own.join("native.txt"),&output.stdout).unwrap();std::fs::write(own.join("stderr.txt"),&output.stderr).unwrap();stop.store(true,Ordering::Release);if let Some(listener)=listener{listener.join().unwrap();}assert!(output.status.success(),"{case}: {} {}",String::from_utf8_lossy(&output.stdout),String::from_utf8_lossy(&output.stderr));if delay>=250&&(expect||case=="over-budget"){assert!(queued_samples>=10,"Shared pending was unavailable while durable claim was queued: {queued_samples}");}
  let claim=own.join("claims/original");if expect{assert_eq!(std::fs::read(&claim).unwrap().len(),20);assert!(claim.with_extension("startup.json").is_file());}if case=="loader-over-budget"{assert!(!claim.exists());assert!(pending.lock().unwrap().as_ref().unwrap().owner.is_none());}evidence.push(serde_json::json!({"case":case,"claimDelayMs":delay,"loaderDelayMs":loader_delay,"budgetMs":budget,"success":expect,"elapsedMs":began.elapsed().as_millis(),"maximumPendingProbeWallUs":maximum_lock,"responsiveQueuedSamples":queued_samples,"actualWrapperBrokerPipe":true,"actualNoita":false}));
 }
 std::fs::write(root.join("results.json"),serde_json::to_vec_pretty(&evidence).unwrap()).unwrap();std::fs::write(repo.join("spikes/noita-entry/.build/g3-startup-repair-client-20261017-01/native-result-location.txt"),root.to_string_lossy().as_bytes()).unwrap();
}
